// Dev tool: regenerates src/drivers/mssql/executionPlan/showplanSchema.generated.ts and
// showplanStrings.generated.ts from sqltoolsservice's sources: showplanxml.cs (classes generated by
// xsd.exe from showplanxml.xsd) and the English strings of Localization/sr.strings.
//
// sqltoolsservice reads a plan with XmlSerializer into those classes, then walks them by .NET
// reflection: the order of a class's properties, their CLR types, the "...Specified" flags and the
// element names of choice groups decide which properties a plan node gets and in which order. This
// tool keeps exactly that metadata (no code): see deserialize.ts and objectModel.ts for its use.
//
// Usage: node tools/gen-showplan-schema.mjs <directory>
// where <directory> holds sqltoolsservice's src/Microsoft.SqlTools.ServiceLayer (commit named in
// docs/execution-plan-analysis.md; MIT licensed). Only the strings the execution plan code uses
// are kept: the SR keys named in the C# files of PORTED.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const sourceRoot = process.argv[2];
if (!sourceRoot) {
    console.error("usage: node tools/gen-showplan-schema.mjs <sqltoolsservice directory>");
    process.exit(1);
}
const serviceLayer = path.join(sourceRoot, "src/Microsoft.SqlTools.ServiceLayer");
const lines = fs
    .readFileSync(path.join(serviceLayer, "ExecutionPlan/ShowPlan/showplanxml.cs"), "utf8")
    .split(/\r?\n/);
const root = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const targetDir = path.join(root, "src/drivers/mssql/executionPlan");
const PORTED = [
    "ExecutionPlan/ExecutionPlanGraphUtils.cs",
    "ExecutionPlan/ShowPlan/Attributes.cs",
    "ExecutionPlan/ShowPlan/FilterTypeParser.cs",
    "ExecutionPlan/ShowPlan/Node.cs",
    "ExecutionPlan/ShowPlan/ObjectWrapperTypeConverter.cs",
    "ExecutionPlan/ShowPlan/Operation.cs",
    "ExecutionPlan/ShowPlan/OperationTable.cs",
    "ExecutionPlan/ShowPlan/PropertyFactory.cs",
    "ExecutionPlan/ShowPlan/RelOpTypeParser.cs",
    "ExecutionPlan/ShowPlan/RunTimeCounters.cs",
    "ExecutionPlan/ShowPlan/XmlPlanNodeBuilder.cs",
    "ExecutionPlan/ShowPlan/XmlPlanParser.cs",
];

const classes = {};
const enums = {};
let current = null; // { kind: "class" | "enum", name }
let attributes = []; // attribute lines seen since the last member

const ATTRIBUTE = /^\s*\[System\.Xml\.Serialization\.(\w+)Attribute\((.*)\)\]\s*$/;
const CLASS = /^\s*public partial class (\w+)(?: : (\w+))? \{$/;
const ENUM = /^\s*public enum (\w+) \{$/;
const PROPERTY = /^\s{8}public ([\w.[\]]+) (\w+) \{$/;
const ENUM_MEMBER = /^\s{8}(\w+),$/;

/** Parses the arguments of an XmlSerializer attribute: positional strings, typeof() and Name=value. */
function parseArguments(text) {
    const positional = [];
    const named = {};
    for (const part of text.split(/,\s*/).filter(Boolean)) {
        const namedMatch = /^(\w+)=(.*)$/.exec(part);
        const value = (raw) => {
            const str = /^"(.*)"$/.exec(raw);
            if (str) return str[1];
            const type = /^typeof\(([\w.]+)\)$/.exec(raw);
            if (type) return { type: type[1] };
            return raw;
        };
        if (namedMatch) named[namedMatch[1]] = value(namedMatch[2]);
        else positional.push(value(part));
    }
    return { positional, named };
}

for (const line of lines) {
    let m;
    if ((m = CLASS.exec(line))) {
        current = { kind: "class", name: m[1] };
        classes[m[1]] = { base: m[2], members: [] };
        attributes = [];
        continue;
    }
    if ((m = ENUM.exec(line))) {
        current = { kind: "enum", name: m[1] };
        enums[m[1]] = [];
        attributes = [];
        continue;
    }
    if ((m = ATTRIBUTE.exec(line))) {
        attributes.push({ name: m[1], ...parseArguments(m[2]) });
        continue;
    }
    if (current?.kind === "enum" && (m = ENUM_MEMBER.exec(line))) {
        const xmlEnum = attributes.find((a) => a.name === "XmlEnum");
        enums[current.name].push(xmlEnum ? [m[1], xmlEnum.positional[0]] : [m[1]]);
        attributes = [];
        continue;
    }
    if (current?.kind === "class" && (m = PROPERTY.exec(line))) {
        const [, type, name] = m;
        const member = { name, type };
        const has = (n) => attributes.filter((a) => a.name === n);
        if (has("XmlIgnore").length) member.ignore = true;
        else if (has("XmlAnyElement").length) member.anyElement = true;
        else if (has("XmlAnyAttribute").length) member.anyAttribute = true;
        else if (has("XmlAttribute").length) {
            member.attribute = has("XmlAttribute")[0].positional[0] ?? name;
        } else if (has("XmlArrayItem").length) {
            const items = has("XmlArrayItem");
            member.array = name;
            member.arrayItem = items.find((a) => !a.named.NestingLevel).positional[0];
            const nested = items.find((a) => a.named.NestingLevel === "1");
            if (nested) member.arrayItemNested = nested.positional[0];
        } else {
            const elements = has("XmlElement");
            const named = elements.filter((a) => typeof a.positional[0] === "string");
            member.elements = named.length
                ? named.map((a) =>
                      a.positional[1] ? [a.positional[0], a.positional[1].type] : [a.positional[0]],
                  )
                : [[name]];
            const order = elements.find((a) => a.named.Order !== undefined)?.named.Order;
            if (order !== undefined) member.order = Number(order);
            if (has("XmlChoiceIdentifier").length)
                member.choice = has("XmlChoiceIdentifier")[0].positional[0];
        }
        classes[current.name].members.push(member);
        attributes = [];
        continue;
    }
    if (/^\s*(public|private|\}|get|set|return|this\.)/.test(line)) {
        // Fields, accessors and closing braces separate members: attributes never span them.
        if (!/^\s*\[/.test(line)) attributes = [];
    }
}

// Sanity checks: every type a member names is a class, an enum or a CLR type we know.
const KNOWN = new Set([
    "string",
    "bool",
    "int",
    "ulong",
    "double",
    "object",
    "System.DateTime",
    "System.Xml.XmlElement",
    "System.Xml.XmlAttribute",
]);
for (const [className, cls] of Object.entries(classes)) {
    if (cls.base && !classes[cls.base]) throw new Error(`${className}: unknown base ${cls.base}`);
    for (const member of cls.members) {
        const element = member.type.replace(/(\[\])+$/, "");
        if (!KNOWN.has(element) && !classes[element] && !enums[element]) {
            throw new Error(`${className}.${member.name}: unknown type ${member.type}`);
        }
    }
}

const out = [
    "// Generated by tools/gen-showplan-schema.mjs from sqltoolsservice's showplanxml.cs (classes",
    "// generated by xsd.exe from Microsoft's showplanxml.xsd, MIT). Do not edit by hand.",
    "/*---------------------------------------------------------------------------------------------",
    " *  Copyright (c) Microsoft Corporation. All rights reserved.",
    " *  Licensed under the MIT License. See License.txt in the project root for license information.",
    " *--------------------------------------------------------------------------------------------*/",
    "",
    'import type { SchemaClass } from "./schemaTypes";',
    "",
    "/** Classes, in declaration order of their properties (the order .NET reflection returns). */",
    `export const SHOWPLAN_CLASSES: Record<string, SchemaClass> = ${JSON.stringify(classes, null, 4)};`,
    "",
    "/** Enums: [member name, XML value when it differs]. */",
    `export const SHOWPLAN_ENUMS: Record<string, string[][]> = ${JSON.stringify(enums)};`,
    "",
];
fs.writeFileSync(path.join(targetDir, "showplanSchema.generated.ts"), out.join("\n"));
console.log(`${Object.keys(classes).length} classes, ${Object.keys(enums).length} enums`);

// Strings: "Key = value" or "Key(params) = value" lines; srgen turns \r, \n, \t and \\ into characters.
const keys = new Set();
for (const file of PORTED) {
    const code = fs.readFileSync(path.join(serviceLayer, file), "utf8");
    for (const m of code.matchAll(/\bSR\.(?:Keys\.)?(\w+)/g)) keys.add(m[1]);
}
keys.delete("GetString");
const strings = {};
const ESCAPES = { r: "\r", n: "\n", t: "\t", "\\": "\\" };
for (const line of fs
    .readFileSync(path.join(serviceLayer, "Localization/sr.strings"), "utf8")
    .split(/\r?\n/)) {
    const m = /^(\w+)(?:\([^)]*\))?\s*=\s?(.*)$/.exec(line);
    if (!m || !keys.has(m[1])) continue;
    strings[m[1]] = m[2].replace(/\\([rnt\\])/g, (_, c) => ESCAPES[c]);
}
const missing = [...keys].filter((k) => !(k in strings));
if (missing.length) throw new Error(`keys missing from sr.strings: ${missing.join(", ")}`);
const sorted = Object.fromEntries(
    Object.entries(strings).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)),
);
fs.writeFileSync(
    path.join(targetDir, "showplanStrings.generated.ts"),
    [
        "// Generated by tools/gen-showplan-schema.mjs from sqltoolsservice's Localization/sr.strings",
        "// (English): the strings the execution plan code uses. Do not edit by hand.",
        "/*---------------------------------------------------------------------------------------------",
        " *  Copyright (c) Microsoft Corporation. All rights reserved.",
        " *  Licensed under the MIT License. See License.txt in the project root for license information.",
        " *--------------------------------------------------------------------------------------------*/",
        "",
        `export const SR: Record<string, string> = ${JSON.stringify(sorted, null, 4)};`,
        "",
    ].join("\n"),
);
console.log(`${Object.keys(sorted).length} strings`);
